// Generates src/tokens/tokens.stylex.ts and src/tokens/themes.ts from src/tokens/source.ts.
// Usage: pnpm --filter paper-ui tokens. tests/tokens.test.ts fails while the generated files are stale.
import { writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import * as source from '../src/tokens/source.ts'

const header = '// Generated by scripts/tokens.ts from source.ts. Edit source.ts, then run `pnpm --filter paper-ui tokens`.\n'

const key = (name: string) => (/^[A-Za-z_$][\w$]*$/u.test(name) ? name : `'${name}'`)

const entries = (values: Record<string, string>, note?: (name: string) => string | undefined) =>
  Object.entries(values)
    .map(([name, value]) => {
      const comment = note?.(name)
      return `  ${key(name)}: '${value}',${comment ? ` // ${comment}` : ''}`
    })
    .join('\n')

const entry = (ref: string) => {
  const [ramp, step] = ref.split('.') as [keyof typeof source.palette, string]
  const value = (source.palette[ramp] as Record<string, string>)[step]
  if (!value) throw new Error(`Unknown palette entry ${ref}`)
  return value
}

const resolve = (value: source.ColorValue) =>
  typeof value === 'string'
    ? entry(value)
    : `color-mix(in srgb, ${entry(value.mix)} ${value.amount}%, ${value.with ? entry(value.with) : 'transparent'})`

const describe = (value: source.ColorValue) =>
  typeof value === 'string' ? value : `${value.amount}% ${value.mix} with ${value.with ?? 'transparent'}`

const themeColors = (theme: source.Theme) => ({
  ...Object.fromEntries(source.colorRoleNames.map(role => [role, resolve(source.colorRoles[theme][role])])),
  scheme: theme,
})

const colorNote = (theme: source.Theme) => (role: string) =>
  role in source.colorRoles[theme] ? describe(source.colorRoles[theme][role as source.ColorRole]) : undefined

const scales = {
  space: source.space,
  size: source.size,
  fluid: source.fluid,
  measure: source.measure,
  font: source.font,
  fontSize: source.fontSize,
  lineHeight: source.lineHeight,
  fontWeight: source.fontWeight,
  tracking: source.tracking,
  type: source.type,
  decoration: source.decoration,
  radius: source.radius,
  border: source.border,
  shadow: source.shadow,
  motion: source.motion,
  glyph: source.glyph,
  blur: source.blur,
  ratio: source.ratio,
  opacity: source.opacity,
  zIndex: source.zIndex,
} as const

const group = (name: string, values: Record<string, string>, note?: (name: string) => string | undefined) =>
  `export const ${name} = stylex.defineVars({\n${entries(values, note)}\n})\n`

// Responsive values list their conditions in source order, so later (narrower) breakpoints win.
const responsiveGroup = (name: string, values: Record<string, string | source.Responsive>) =>
  `export const ${name} = stylex.defineVars({\n${Object.entries(values)
    .map(([key, value]) =>
      typeof value === 'string'
        ? `  ${key}: '${value}',`
        : `  ${key}: {\n${Object.entries(value)
            .map(([condition, length]) =>
              `    ${condition === 'default' ? 'default' : `'${source.breakpoints[condition as keyof typeof source.breakpoints]}'`}: '${length}',`,
            )
            .join('\n')}\n  },`,
    )
    .join('\n')}\n})\n`

const tokens = [
  header,
  "import * as stylex from '@stylexjs/stylex'\n",
  group('color', themeColors('light'), colorNote('light')),
  group('density', source.density.comfortable),
  responsiveGroup('page', source.page),
  ...Object.entries(scales).map(([name, values]) => group(name, values as Record<string, string>)),
  `export const breakpoints = stylex.defineConsts({\n${entries(source.breakpoints)}\n})\n`,
  '/** Marks the element that carries `data-theme`, so styles can follow the theme with `stylex.when.ancestor`. */\n' +
    'export const themeScope = stylex.defineMarker()\n',
].join('\n')

const theme = (name: string, groupName: string, values: Record<string, string>, note?: (n: string) => string | undefined) =>
  `export const ${name} = stylex.createTheme(${groupName}, {\n${entries(values, note)}\n})\n`

const themes = [
  header,
  "import * as stylex from '@stylexjs/stylex'\nimport { color, density } from './tokens.stylex'\n",
  theme('lightTheme', 'color', themeColors('light'), colorNote('light')),
  theme('darkTheme', 'color', themeColors('dark'), colorNote('dark')),
  theme('comfortableDensity', 'density', source.density.comfortable),
  theme('compactDensity', 'density', source.density.compact),
].join('\n')

/** The generated files, keyed by their path from the package root. */
export const generatedTokenFiles = { 'src/tokens/tokens.stylex.ts': tokens, 'src/tokens/themes.ts': themes }

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  for (const [path, content] of Object.entries(generatedTokenFiles)) await writeFile(new URL(`../${path}`, import.meta.url), content)
}
